"""Portable tray actions; no transcription or model dependencies."""
import os
from pathlib import Path
import sys
import winreg

RUN_KEY = r"Software\Microsoft\Windows\CurrentVersion\Run"
APPROVAL_KEY = r"Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run"
VALUE_NAME = "EXPC-WLK"
RESTART_EVENT = r"Local\WhisperKeyPortableRestart"


def launcher_path():
    installed = os.environ.get("EXPC_WLK_LAUNCHER")
    if installed:
        return Path(installed).resolve()
    return Path(sys.executable).resolve().parents[2] / "EXPC-WLK.exe"


def metadata_root():
    installed = os.environ.get("EXPC_WLK_METADATA_ROOT")
    if installed:
        return Path(installed).resolve()
    return launcher_path().parent / "WhisperKey"


def model_root():
    installed = os.environ.get("EXPC_WLK_MODEL_ROOT")
    if installed:
        return Path(installed).resolve()
    return metadata_root() / "models"


def _read(key_path):
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, key_path) as key:
            return winreg.QueryValueEx(key, VALUE_NAME)[0]
    except FileNotFoundError:
        return None


def autostart_enabled(launcher=None):
    command = _read(RUN_KEY)
    expected = '"' + str(launcher or launcher_path()) + '"'
    approved = _read(APPROVAL_KEY)
    disabled = isinstance(approved, bytes) and approved[:1] in (b"\x03", b"\x07")
    return isinstance(command, str) and os.path.normcase(command) == os.path.normcase(expected) and not disabled


def set_autostart(enabled, launcher=None):
    path = Path(launcher or launcher_path()).resolve()
    if enabled and not path.is_file():
        raise FileNotFoundError(f"Portable launcher missing: {path}")
    with winreg.CreateKey(winreg.HKEY_CURRENT_USER, RUN_KEY) as key:
        if enabled:
            winreg.SetValueEx(key, VALUE_NAME, 0, winreg.REG_SZ, '"' + str(path) + '"')
        else:
            try:
                winreg.DeleteValue(key, VALUE_NAME)
            except FileNotFoundError:
                pass
    # Remove this app's Task Manager override when explicitly toggled by the user.
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, APPROVAL_KEY, 0, winreg.KEY_SET_VALUE) as key:
            try:
                winreg.DeleteValue(key, VALUE_NAME)
            except FileNotFoundError:
                pass
    except FileNotFoundError:
        pass


def request_restart():
    import win32event
    event_name = os.environ.get("EXPC_WLK_RESTART_EVENT", RESTART_EVENT)
    handle = win32event.OpenEvent(2, False, event_name)  # EVENT_MODIFY_STATE
    try:
        win32event.SetEvent(handle)
    finally:
        handle.Close()
